pr_body:
Provide a plugin hook to access and alter vite config. It imitates rollup's [options](https://rollupjs.org/guide/en/#options) hook.

Usage:
```ts
import { Plugin } from 'vite'

export const changeConfigPlugin1: Plugin = {
  changeConfig: (prev) => {
    prev.define['__changeConfigPlugin1__'] = 'success'
    prev.plugins.push(changeConfigPlugin2)
    return prev
  }
}

const changeConfigPlugin2: Plugin = {
  changeConfig: (prev) => {
    prev.define['__changeConfigPlugin2__'] = 'success'
    return prev
  }
}
```

fix: https://github.com/vitejs/vite/issues/1162

comments:
The plugin API in my mind is like this: 

```ts
const myVitePlugin = {
   jsx: (prevJSX) => {
       if (prevJSX === undefined) return "react";
       return prevJSX;
   },
   optimizeDeps: (prevOptimizeDeps) => {
       if (!prevOptimizeDeps.inlude.find("react") && !prevOptimizeDeps.inlude.find("react-dom"))
         prevOptimizeDeps.inlude.push("react", "react-dom");
       return prevOptimizeDeps;
   }

}

```
